INSERT INTO monk_intro_text_guard VALUES(@monk_intro_text_safe);
UPDATE quest_template q JOIN quest_template_locale l ON l.ID=q.ID AND l.locale='enUS'
SET q.`LogTitle`=l.`LogTitle`, q.`LogDescription`=l.`LogDescription`, q.`QuestDescription`=l.`QuestDescription`, q.`QuestCompletionLog`=l.`QuestCompletionLog`
WHERE @monk_intro_text_safe=1 AND q.ID=12103;
